package net.civeira.phylax.feature.oauth.client.domain.gateway;

import java.util.Optional;

import net.civeira.phylax.feature.oauth.client.domain.DcrRegistrationRules;
import net.civeira.phylax.feature.oauth.client.domain.DynamicClientData;
import net.civeira.phylax.feature.oauth.client.domain.DynamicClientRequest;

/**
 * Persistence of the clients registered through DCR (RFC 7591 / 7592, task 2.1).
 *
 * <p>
 * Every operation is scoped to the tenant of the endpoint: a client is born with it and is only
 * managed from it. Secrets and registration access tokens are stored as digests and never read
 * back.
 */
public interface DynamicClientGateway {

  /**
   * What the tenant lets clients register.
   *
   * @param tenant tenant name
   * @return the rules, disabled when the tenant does not exist or has no DCR
   */
  DcrRegistrationRules readRegistrationRules(String tenant);

  /**
   * Stores a new client of the tenant, already validated.
   *
   * @param tenant tenant name
   * @param clientId new client identifier
   * @param clientSecret secret of a confidential client, empty for a public one
   * @param registrationAccessToken RFC 7592 management token
   * @param request normalized metadata
   * @return the stored metadata
   */
  DynamicClientData create(String tenant, String clientId, Optional<String> clientSecret,
      String registrationAccessToken, DynamicClientRequest request);

  /**
   * Finds a dynamically registered client of the tenant by its registration access token.
   *
   * @param tenant tenant name
   * @param clientId client identifier
   * @param registrationAccessToken token presented in clear
   * @return the metadata, without secrets
   */
  Optional<DynamicClientData> find(String tenant, String clientId, String registrationAccessToken);

  /**
   * Replaces the metadata of a dynamically registered client of the tenant.
   *
   * @param tenant tenant name
   * @param clientId client identifier
   * @param registrationAccessToken token presented in clear
   * @param request normalized metadata
   * @return the stored metadata, empty when the client or token does not match
   */
  Optional<DynamicClientData> update(String tenant, String clientId, String registrationAccessToken,
      DynamicClientRequest request);

  /**
   * Deletes a dynamically registered client of the tenant.
   *
   * @param tenant tenant name
   * @param clientId client identifier
   * @param registrationAccessToken token presented in clear
   * @return true when deleted
   */
  boolean delete(String tenant, String clientId, String registrationAccessToken);
}
